module.exports = async ({github, context, core}) => {
  try {
    // Read the latest report to get critical issue details
    const fs = require('fs');
    const path = require('path');
    
    const reportsDir = '.github/issue-monitoring/reports';
    const latestReportPath = path.join(reportsDir, 'latest-report.json');
    
    if (!fs.existsSync(latestReportPath)) {
      core.warning('No latest report found for critical notifications');
      return;
    }
    
    const report = JSON.parse(fs.readFileSync(latestReportPath, 'utf8'));
    
    // Determine notification urgency
    const criticalCount = report.summary.criticalIssues || 0;
    const needsAttentionCount = report.summary.needsAttention || 0;
    const activeBlockers = report.summary.activeBlockers || 0;
    const riskScore = report.summary.riskScore || 0;
    
    // Calculate urgency level
    let urgencyLevel = 'low';
    let notifications = [];
    
    if (criticalCount > 0) {
      urgencyLevel = 'high';
      notifications.push({
        type: 'critical_issues',
        message: `🚨 ${criticalCount} critical issues require immediate attention`,
        action: 'Review and assign critical issues'
      });
    }
    
    if (needsAttentionCount > 0) {
      if (urgencyLevel !== 'high') urgencyLevel = 'medium';
      notifications.push({
        type: 'stale_issues',
        message: `⚠️ ${needsAttentionCount} issues haven't been updated in >24 hours`,
        action: 'Check progress on stale issues'
      });
    }
    
    if (activeBlockers > 0) {
      if (urgencyLevel !== 'high') urgencyLevel = 'medium';
      notifications.push({
        type: 'blockers',
        message: `🚫 ${activeBlockers} active blockers are preventing progress`,
        action: 'Resolve blocking issues'
      });
    }
    
    if (riskScore > 80) {
      urgencyLevel = 'high';
      notifications.push({
        type: 'high_risk',
        message: `⚠️ High risk score: ${riskScore}/100`,
        action: 'Review project health and take corrective action'
      });
    }
    
    // Create notification content
    let notificationBody = `# 🚨 Critical Issue Alert\\n\\n`;
    notificationBody += `**Urgency Level**: ${urgencyLevel.toUpperCase()}\\n`;
    notificationBody += `**Generated**: ${new Date().toLocaleString()}\\n\\n`;
    
    if (notifications.length > 0) {
      notificationBody += `## Issues Requiring Attention\\n\\n`;
      notifications.forEach((notification, index) => {
        notificationBody += `${index + 1}. ${notification.message}\\n`;
        notificationBody += `   **Action**: ${notification.action}\\n\\n`;
      });
    }
    
    // Add specific issue details
    if (report.sections && report.sections.critical) {
      notificationBody += `## Critical Issue Details\\n\\n`;
      notificationBody += report.sections.critical;
    }
    
    // Add quick action items
    notificationBody += `## 🎯 Immediate Actions Required\\n\\n`;
    
    if (criticalCount > 0) {
      notificationBody += `- [ ] Review all ${criticalCount} critical issues\\n`;
      notificationBody += `- [ ] Ensure critical issues have assignees\\n`;
      notificationBody += `- [ ] Set daily check-ins for critical issues\\n`;
    }
    
    if (needsAttentionCount > 0) {
      notificationBody += `- [ ] Follow up on ${needsAttentionCount} stale issues\\n`;
      notificationBody += `- [ ] Request status updates from assignees\\n`;
    }
    
    if (activeBlockers > 0) {
      notificationBody += `- [ ] Identify root causes of ${activeBlockers} blockers\\n`;
      notificationBody += `- [ ] Escalate external dependencies\\n`;
      notificationBody += `- [ ] Create workaround plans where possible\\n`;
    }
    
    notificationBody += `\\n## 📊 Dashboard\\n\\n`;
    notificationBody += `[View Full Dashboard](./.github/issue-monitoring/reports/dashboard.md)\\n`;
    notificationBody += `[Latest Report](./.github/issue-monitoring/reports/latest-report.json)\\n\\n`;
    
    notificationBody += `---\\n*Automated alert generated by Issue Monitoring System*`;
    
    // Post notification based on urgency level
    if (urgencyLevel === 'high') {
      // Create a new issue for high urgency
      await github.rest.issues.create({
        owner: context.repo.owner,
        repo: context.repo.repo,
        title: `🚨 URGENT: Critical Issues Alert - ${new Date().toISOString().split('T')[0]}`,
        body: notificationBody,
        labels: ['urgent', 'monitoring-alert', 'critical'],
        assignees: await getProjectLeads(github, context)
      });
      
      core.info('Created urgent issue for critical alert');
      
    } else if (urgencyLevel === 'medium') {
      // Comment on the monitoring issue
      const monitoringIssueNumber = 16; // Dedicated monitoring issue
      
      await github.rest.issues.createComment({
        owner: context.repo.owner,
        repo: context.repo.repo,
        issue_number: monitoringIssueNumber,
        body: notificationBody
      });
      
      core.info('Posted medium urgency notification to monitoring issue');
      
    } else {
      // Just log for low urgency
      core.info('Low urgency - notification logged only');
    }
    
    // Send team notifications via discussions if enabled
    if (urgencyLevel === 'high') {
      await createTeamDiscussion(github, context, notificationBody, urgencyLevel);
    }
    
    return {
      urgencyLevel,
      notificationsSent: notifications.length,
      method: urgencyLevel === 'high' ? 'new_issue' : 'comment'
    };
    
  } catch (error) {
    core.error(`Error sending critical notifications: ${error.message}`);
    throw error;
  }
};

async function getProjectLeads(github, context) {
  try {
    // Get repository collaborators with admin/maintain permissions
    const { data: collaborators } = await github.rest.repos.listCollaborators({
      owner: context.repo.owner,
      repo: context.repo.repo,
      permission: 'admin'
    });
    
    // Return up to 3 leads for assignment
    return collaborators.slice(0, 3).map(c => c.login);
    
  } catch (error) {
    // Fallback to repository owner
    return [context.repo.owner];
  }
}

async function createTeamDiscussion(github, context, content, urgencyLevel) {
  try {
    // Check if discussions are enabled
    const { data: repo } = await github.rest.repos.get({
      owner: context.repo.owner,
      repo: context.repo.repo
    });
    
    if (repo.has_discussions) {
      // Create a team discussion for high urgency issues
      await github.rest.teams.createDiscussionInOrg({
        org: context.repo.owner,
        team_slug: 'developers', // Adjust team slug as needed
        title: `🚨 Critical Issues Alert - ${urgencyLevel.toUpperCase()}`,
        body: content
      });
    }
    
  } catch (error) {
    // Discussions might not be available - ignore error
    console.log('Team discussions not available or team not found');
  }
}